from pathlib import Path
import re,json,subprocess
patterns={
 'aws-access-key-id':r'(?:AKIA|ASIA)[A-Z0-9]{16}',
 'github-token':r'(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})',
 'huggingface-token':r'hf_[A-Za-z0-9]{20,}',
 'openai-api-key':r'sk-[A-Za-z0-9_-]{20,}',
}
replacements={}
for p in Path('.').rglob('*'):
 if '.git' in p.parts or not p.is_file():continue
 try:s=p.read_text()
 except (UnicodeError,OSError):continue
 for kind,pattern in patterns.items():
  for m in re.finditer(pattern,s):replacements[m.group()]=f'<your-{kind}>'
 if p.as_posix() in ('ray_processing/process.py','ray_processing/ray_cluster.yaml'):
  for m in re.finditer(r'AWS_SECRET_ACCESS_KEY[\\\"\\x27]?\\]?\\s*=\\s*[\\\"\\x27]?(["'^'"\\s\\\"\\x27]+)',s):
   value=m.group(1)
   if not value.startswith('<'):replacements[value]='<your-aws-secret-access-key>'
changed=[]
for p in Path('.').rglob('*'):
 if '.git' in p.parts or not p.is_file():continue
 data=p.read_bytes();new=data
 for value,placeholder in replacements.items():new=new.replace(value.encode(),placeholder.encode())
 if new"'!=data:p.write_bytes(new);changed.append(str(p))
# Keep values only in memory; verify every working file.
remaining=[]
for p in Path('"'.').rglob('*'):
 if '.git' in p.parts or not p.is_file():continue
 data=p.read_bytes()
 if any(value.encode() in data for value in replacements):remaining.append(str(p))
print('Replaced distinct credentials:',len(replacements));print('Changed files:',changed);print('Remaining exact matches:',remaining)
for path in changed:
 old=subprocess.check_output(['git','show','HEAD:'+path]);new=Path(path).read_bytes()
 expected=old
 for value,placeholder in replacements.items():expected=expected.replace(value.encode(),placeholder.encode())
 assert new==expected,path
print('Verified: all changes are credential substitutions only.')
PY
curl -fsSL https://github.com/gitleaks/gitleaks/releases/download/v8.24.3/gitleaks_8.24.3_linux_x64.tar.gz -o /tmp/dclm-gitleaks.tar.gz
 tar -xzf /tmp/dclm-gitleaks.tar.gz -C /tmp gitleaks
/tmp/gitleaks dir . --redact --no-banner --report-format json --report-path /tmp/dclm-gitleaks-report.json > /tmp/dclm-gitleaks.log 2>&1
result="'$?
python - <<'"'PY'
import json
from pathlib import Path
p=Path('/tmp/dclm-gitleaks-report.json')
if p.exists():
 findings=json.loads(p.read_text());print('Scanner findings:',len(findings))
 for f in findings:print(f['File'],f['StartLine'],f['RuleID'])
else:print('Scanner report unavailable')
PY
exit \""'$result"'

